package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.nio.ByteBuffer;
import java.util.*;

/** Committed local intent precedes configuration mutation; completion follows actual catalogue publication. */
public record RatisTopologyRelocationRecord(Action action,TopologyChange.Definition definition,UUID catalogue,ApplyPosition catalogueCut,byte[] sourceConfiguration,byte[] targetConfiguration) {
    public static final int MAGIC=0x52545243,MAX_BYTES=TopologyChange.MAX_DEFINITION_BYTES+2*65536+49;
    public enum Action { AUTHORIZE, COMPLETE }
    public RatisTopologyRelocationRecord {Objects.requireNonNull(action);Objects.requireNonNull(definition);Objects.requireNonNull(catalogue);Objects.requireNonNull(catalogueCut);if(definition.kind()!=TopologyChange.Kind.RELOCATE || catalogueCut.term()<1 || catalogueCut.index()<1 || sourceConfiguration==null || sourceConfiguration.length<1 || sourceConfiguration.length>65536 || targetConfiguration==null || targetConfiguration.length<1 || targetConfiguration.length>65536)throw new IllegalArgumentException("Invalid relocation record");sourceConfiguration=sourceConfiguration.clone();targetConfiguration=targetConfiguration.clone();try{RatisRangeStateMachine.requireSchemaMembership(definition.parents().getFirst(),sourceConfiguration);RatisRangeStateMachine.requireSchemaMembership(definition.targets().getFirst(),targetConfiguration);}catch(java.io.IOException invalid){throw new IllegalArgumentException("Relocation record membership differs",invalid);}}
    @Override public byte[] sourceConfiguration(){return sourceConfiguration.clone();}@Override public byte[] targetConfiguration(){return targetConfiguration.clone();}
    public byte[] encode(){byte[] d=definition.encode();var out=ByteBuffer.allocate(49+d.length+sourceConfiguration.length+targetConfiguration.length).putInt(MAGIC).put((byte)action.ordinal());put(out,d);out.putLong(catalogue.getMostSignificantBits()).putLong(catalogue.getLeastSignificantBits()).putLong(catalogueCut.term()).putLong(catalogueCut.index());put(out,sourceConfiguration);put(out,targetConfiguration);return out.array();}
    private static void put(ByteBuffer out,byte[] bytes){out.putInt(bytes.length).put(bytes);}
    public static boolean isRecord(byte[] bytes){return bytes!=null && bytes.length>=4 && ByteBuffer.wrap(bytes).getInt()==MAGIC;}
    public static RatisTopologyRelocationRecord decode(byte[] bytes){if(bytes==null || bytes.length<49 || bytes.length>MAX_BYTES)throw new IllegalArgumentException("Invalid relocation record length");var in=ByteBuffer.wrap(bytes);if(in.getInt()!=MAGIC)throw new IllegalArgumentException("Invalid relocation record tag");int action=in.get()&255;if(action>=Action.values().length)throw new IllegalArgumentException("Invalid relocation action");var definition=TopologyChange.Definition.decode(ScopedTransactionRpc.blob(in,TopologyChange.MAX_DEFINITION_BYTES,false));if(in.remaining()<40)throw new IllegalArgumentException("Truncated relocation identity");var catalogue=new UUID(in.getLong(),in.getLong());var cut=new ApplyPosition(in.getLong(),in.getLong());var source=ScopedTransactionRpc.blob(in,65536,false);var target=ScopedTransactionRpc.blob(in,65536,false);if(in.hasRemaining())throw new IllegalArgumentException("Relocation record trailing bytes");var result=new RatisTopologyRelocationRecord(Action.values()[action],definition,catalogue,cut,source,target);if(!Arrays.equals(bytes,result.encode()))throw new IllegalArgumentException("Noncanonical relocation record");return result;}
    @Override public boolean equals(Object other){return other instanceof RatisTopologyRelocationRecord record && Arrays.equals(encode(),record.encode());}@Override public int hashCode(){return Arrays.hashCode(encode());}
}
